from pathlib import Path
import re

p=Path('market-view.html')
s=p.read_text()
if "const APP_VERSION='3.5.1'" not in s:
    raise SystemExit('Expected Market Navigator 3.5.1 baseline')

def replace_once(old,new,label):
    global s
    if old not in s:
        raise SystemExit('Missing patch anchor: '+label)
    s=s.replace(old,new,1)

# Version
s=s.replace('<title>Market Navigator 3.5.1</title>','<title>Market Navigator 3.6</title>')
s=s.replace('Version 3.5.1</small>','Version 3.6</small>')
s=s.replace('Market Navigator 3.5.1</div>','Market Navigator 3.6</div>')
s=s.replace("const APP_VERSION='3.5.1'","const APP_VERSION='3.6.0'")

# Compact small multiples and sticky horizon selector.
s=s.replace(".rangebar{margin:8px 0}",".rangebar{position:sticky;top:0;z-index:18;margin:0 0 8px;padding:8px 0;background:#09111f;border-bottom:1px solid var(--line)}")
s=s.replace(".marketGrid,.macroGrid{grid-template-columns:repeat(3,minmax(0,1fr))}",".marketGrid{grid-template-columns:repeat(4,minmax(0,1fr))}.macroGrid{grid-template-columns:repeat(3,minmax(0,1fr))}")
s=s.replace(".spark{height:72px;width:100%;margin-top:5px;touch-action:none;cursor:crosshair}",".spark{height:42px;width:100%;margin-top:5px;touch-action:none;cursor:crosshair}")
s=s.replace("@media(max-width:1050px){.compositeGrid,.marketGrid,.macroGrid,.providerGrid{grid-template-columns:repeat(2,minmax(0,1fr))}}","@media(max-width:1250px){.marketGrid{grid-template-columns:repeat(3,minmax(0,1fr))}.compositeGrid,.macroGrid,.providerGrid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:900px){.marketGrid{grid-template-columns:repeat(2,minmax(0,1fr))}}")

# Standard market horizons. 1D/5D are intraday-aware in detail; longer periods are daily.
replace_once("const HORIZONS={now:{label:'Now',days:5},'7d':{label:'1W',days:7},'1mo':{label:'1M',days:30},ytd:{label:'YTD',ytd:true},'1y':{label:'1Y',days:365},'3y':{label:'3Y',days:1095},'5y':{label:'5Y',days:1825}};",
"const HORIZONS={'1d':{label:'1D',days:1,intraday:true,fetchRange:'1d',interval:'5m'},'5d':{label:'5D',days:7,intraday:true,fetchRange:'5d',interval:'30m'},'1mo':{label:'1M',days:30},'3mo':{label:'3M',days:90},'6mo':{label:'6M',days:180},ytd:{label:'YTD',ytd:true},'1y':{label:'1Y',days:365},'5y':{label:'5Y',days:1825},max:{label:'All',max:true}};","horizons")

# Linear navigation: guided Now -> components -> detail. Ad hoc analysis has its own left-nav destination.
replace_once("const NAV=[['now','◉','Now'],['markets','▥','Markets'],['macro','▤','Macro'],['relationships','⌗','Relationships'],['news','◌','News'],['library','▣','Analysis Library'],['providers','◇','Providers'],['logs','≡','Logs'],['about','?','About']];",
"const NAV=[['now','◉','Now'],['macro','▤','Macro'],['news','◌','News'],['relationships','⌗','Analysis'],['library','▣','Analysis Library'],['providers','◇','Providers'],['logs','≡','Logs'],['about','?','About']];","navigation")

# Yahoo Finance news is part of the feed mix.
replace_once("const FEEDS=['https://feeds.a.dj.com/rss/RSSMarketsMain.xml','https://feeds.bbci.co.uk/news/business/rss.xml','https://www.ft.com/markets?format=rss','https://feeds.marketwatch.com/marketwatch/topstories/','https://www.morningstar.com/rss/market-news'];",
"const FEEDS=['https://feeds.a.dj.com/rss/RSSMarketsMain.xml','https://feeds.bbci.co.uk/news/business/rss.xml','https://www.ft.com/markets?format=rss','https://feeds.marketwatch.com/marketwatch/topstories/','https://www.morningstar.com/rss/market-news','https://finance.yahoo.com/news/rssindex'];","Yahoo Finance RSS")

# Stop turning every collection event into a random toast. Add deterministic progress UI for multi-series work.
replace_once("function esc(s=''){return String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]))}function fmt(v,d=2){return Number.isFinite(v)?v.toLocaleString(undefined,{minimumFractionDigits:d,maximumFractionDigits:d}):'Unavailable'}function pct(v){return Number.isFinite(v)?`${v>=0?'+':''}${v.toFixed(2)}%`:'Unavailable'}function toast(m){const e=$('#toast');e.textContent=m;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2400)}function activity(m=''){const e=$('#activity');e.textContent=m;e.classList.toggle('show',!!m);if(m)toast(m)}",
"function esc(s=''){return String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]))}function fmt(v,d=2){return Number.isFinite(v)?v.toLocaleString(undefined,{minimumFractionDigits:d,maximumFractionDigits:d}):'Unavailable'}function pct(v){return Number.isFinite(v)?`${v>=0?'+':''}${v.toFixed(2)}%`:'Unavailable'}function toast(m){const e=$('#toast');e.textContent=m;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2400)}function activity(m=''){const e=$('#activity');e.textContent=m;e.classList.toggle('show',!!m)}function ensureProgressModal(){let m=$('#progressModal');if(m)return m;m=document.createElement('div');m.id='progressModal';m.className='modal';m.innerHTML=`<div class=\"modalPanel\" style=\"max-width:520px\"><h2 id=\"progressTitle\">Preparing market history</h2><p id=\"progressText\" class=\"muted\"></p><div style=\"height:12px;background:#07101e;border:1px solid var(--line);border-radius:999px;overflow:hidden\"><div id=\"progressBar\" style=\"height:100%;width:0;background:var(--accent);transition:width .2s\"></div></div><div id=\"progressCount\" class=\"tiny muted\" style=\"margin-top:8px\"></div></div>`;document.body.appendChild(m);return m}function progressOpen(title,total){ensureProgressModal();$('#progressTitle').textContent=title;$('#progressText').textContent='Historical data is collected once, aggregated locally, then maintained incrementally.';$('#progressCount').textContent=`0 of ${total}`;$('#progressBar').style.width='0%';$('#progressModal').classList.add('open')}function progressStep(done,total,label){ensureProgressModal();$('#progressCount').textContent=`${done} of ${total} · ${label||''}`;$('#progressBar').style.width=`${total?Math.round(done/total*100):0}%`}function progressClose(){setTimeout(()=>$('#progressModal')?.classList.remove('open'),250)}","activity/progress")

# Daily store special handling for short horizons; all means all stored data.
m=re.search(r"function canonical\(id,data\).*?function exactRangeSeries\(id,r\).*?\}\nasync function loadDbState",s,re.S)
if not m: raise SystemExit('range/coverage block not found')
block=r'''function canonical(id,data){const monthly=META[id]?.policy==='monthly',map=new Map();for(const p of data||[]){if(!Number.isFinite(p?.t)||!Number.isFinite(p?.v))continue;const d=new Date(p.t),k=monthly?`${d.getUTCFullYear()}-${d.getUTCMonth()}`:d.toISOString().slice(0,10),old=map.get(k);if(!old||p.t>=old.t)map.set(k,{t:p.t,v:p.v})}return[...map.values()].sort((a,b)=>a.t-b.t)}function quote(d){if(!d?.length)return null;const a=d.at(-1),b=d[0],prev=d.at(-2)||a;return{value:a.v,time:a.t,count:d.length,changePct:prev.v?(a.v/prev.v-1)*100:null,periodPct:b.v?(a.v/b.v-1)*100:null}}function commonEnd(){const t=Object.keys(META).filter(id=>META[id].symbol&&state.series[id]?.length).map(id=>state.series[id].at(-1).t);return t.length?Math.max(...t):Date.now()}function horizonStart(r,end){if(r==='ytd')return Date.UTC(new Date(end).getUTCFullYear(),0,1);if(r==='max')return 0;const h=HORIZONS[r]||HORIZONS['1mo'];return end-h.days*86400000}function rangeSeries(id,r,common=true){const d=state.series[id]||[];if(!d.length)return[];if(r==='max')return d;const end=common&&META[id]?.symbol?commonEnd():d.at(-1).t;if(r==='1d'){const prior=d.filter(x=>x.t<=end).slice(-2);return prior}const start=horizonStart(r,end);return d.filter(x=>x.t>=start&&x.t<=end+86400000)}function rangeQuote(id,r){return quote(rangeSeries(id,r,true))}function coverage(id,r){const d=rangeSeries(id,r,true),end=META[id]?.symbol?commonEnd():(state.series[id]?.at(-1)?.t||Date.now()),monthly=META[id]?.policy==='monthly';if(r==='max')return{ok:d.length>=2,points:d.length,start:d[0]?.t||null,end:d.at(-1)?.t||null,required:2,spanDays:d.length?Math.max(0,(d.at(-1).t-d[0].t)/86400000):0,targetDays:null};if(r==='1d'){const last=d.at(-1)?.t||0;return{ok:d.length>=2&&end-last<=5*86400000,points:d.length,start:d[0]?.t||null,end:d.at(-1)?.t||null,required:2,spanDays:d.length?Math.max(0,(d.at(-1).t-d[0].t)/86400000):0,targetDays:1}}const start=horizonStart(r,end),days=Math.max(1,(end-start)/86400000);if(r==='5d'){const span=d.length?Math.max(0,(d.at(-1).t-d[0].t)/86400000):0;return{ok:d.length>=3&&span>=3,points:d.length,start:d[0]?.t||null,end:d.at(-1)?.t||null,required:3,spanDays:span,targetDays:days}}const required=monthly?Math.max(2,Math.floor(days/30*.75)):Math.max(3,Math.floor(days*.55)),span=d.length?Math.max(0,(d.at(-1).t-d[0].t)/86400000):0,spanOk=span>=days*.78,latestOk=d.length?end-d.at(-1).t<=Math.max(monthly?45:7,days*.08)*86400000:false;return{ok:d.length>=required&&spanOk&&latestOk,points:d.length,start:d[0]?.t||null,end:d.at(-1)?.t||null,required,spanDays:span,targetDays:days}}function exactRangeSeries(id,r){return coverage(id,r).ok?rangeSeries(id,r,true):[]}
async function loadDbState'''
s=s[:m.start()]+block+s[m.end():]

# Yahoo interval is horizon aware in detail views.
s=s.replace("function yahooUrl(id,range='5d'){return`https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(META[id].symbol)}?range=${range}&interval=1d&includePrePost=true&events=div%2Csplits`}async function fetchJsonRoutes",
"function yahooUrl(id,range='5d',interval='1d'){return`https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(META[id].symbol)}?range=${range}&interval=${interval}&includePrePost=true&events=div%2Csplits`}async function fetchJsonRoutes")
s=s.replace("async function fetchYahoo(id,range='5d'){const j=await fetchJsonRoutes(yahooUrl(id,range),`Yahoo ${META[id].short}`)","async function fetchYahoo(id,range='5d',interval='1d'){const j=await fetchJsonRoutes(yahooUrl(id,range,interval),`Yahoo ${META[id].short}`)")

# Progress-backed historical collection. No refetch if the local aggregate already covers the selected horizon.
m=re.search(r"async function ensureHistory\(id,r\).*?\nfunction signal",s,re.S)
if not m: raise SystemExit('ensure history block not found')
ensure=r'''async function ensureHistory(id,r){if(!META[id].symbol)return coverage(id,r).ok;const target=r==='max'?'5y':r;let c=coverage(id,target);if(c.ok)return true;const m=state.seriesMeta[id]||{},last=m.historyFetchAt||0;if(Date.now()-last<30*60000)return coverage(id,target).ok;state.seriesMeta[id]={...m,id,historyFetchAt:Date.now()};await idbPut('series',state.seriesMeta[id]);await fetchSeries(id,{history:true});return coverage(id,target).ok}async function ensureOverviewHorizon(r){if(r==='1d'||r==='5d')return;const target=r==='max'?'5y':r,ids=['spy','qqq','vix','tenYear','wti','brent','gold','dxy'],missing=ids.filter(id=>!coverage(id,target).ok);if(!missing.length)return;progressOpen(`Preparing ${HORIZONS[r].label} market history`,missing.length);let done=0;try{for(const id of missing){progressStep(done,missing.length,`Fetching ${META[id].short}`);await ensureHistory(id,target);done++;progressStep(done,missing.length,META[id].short);renderNow();await new Promise(x=>setTimeout(x,200))}}finally{progressClose()}}
function signal'''
s=s[:m.start()]+ensure+s[m.end():]

# No false 50: no usable composites means unavailable.
s=s.replace("function regime(){const keys=['risk','rates','energy','defense'],vals=keys.map(k=>compositeSignal(k)).filter(x=>x.available),raw=vals.length?vals.reduce((a,b)=>a+b.score,0)/vals.length:0,score=Math.round(50+raw*35),label=score>=62?'Optimistic':score<=38?'Pessimistic':'Neutral';return{score,label,confidence:Math.round(vals.length/keys.length*100)}}",
"function regime(){const keys=['risk','rates','energy','defense'],vals=keys.map(k=>compositeSignal(k)).filter(x=>x.available);if(!vals.length)return{score:null,label:'Unavailable',confidence:0};const raw=vals.reduce((a,b)=>a+b.score,0)/vals.length,score=Math.round(50+raw*35),label=score>=62?'Optimistic':score<=38?'Pessimistic':'Neutral';return{score,label,confidence:Math.round(vals.length/keys.length*100)}}")
s=s.replace("$('#score').textContent=r.score;","$('#score').textContent=Number.isFinite(r.score)?r.score:'—';")
s=s.replace("${r.score*3.6}deg","${Number.isFinite(r.score)?r.score*3.6:0}deg")

# Remember the guided drill-down parent.
s=s.replace("function openComposite(key){const c=COMPOSITES[key];","function openComposite(key){state.lastComposite=key;const c=COMPOSITES[key];")

# Replace chart renderer: proportionate detail chart, real date labels, y-axis values; sparklines remain axis-free.
m=re.search(r"function setupCanvas\(c\).*?function tooltip\(c,e,list,pad,t0,t1\)",s,re.S)
if not m: raise SystemExit('chart renderer block not found')
chart=r'''function setupCanvas(c){const r=c.getBoundingClientRect(),d=devicePixelRatio||1;c.width=Math.max(1,r.width*d);c.height=Math.max(1,r.height*d);const x=c.getContext('2d');x.setTransform(d,0,0,d,0,0);return{x,w:r.width,h:r.height}}function axisDate(t,span){const d=new Date(t);if(span<=2*86400000)return d.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'});if(span<=50*86400000)return d.toLocaleDateString(undefined,{month:'short',day:'numeric'});if(span<=220*86400000)return d.toLocaleDateString(undefined,{month:'short',day:'numeric'});if(span<=800*86400000)return d.toLocaleDateString(undefined,{month:'short',year:'2-digit'});return String(d.getFullYear())}function axisValue(v){const a=Math.abs(v);return a>=1000?Intl.NumberFormat(undefined,{notation:'compact',maximumFractionDigits:1}).format(v):a>=100?v.toFixed(0):a>=10?v.toFixed(1):v.toFixed(2)}function drawLines(c,list,{axes=true}={}){const{x,w,h}=setupCanvas(c),pad=axes?{l:58,r:12,t:12,b:30}:{l:3,r:3,t:4,b:3},pts=list.flatMap(s=>s.data||[]);x.clearRect(0,0,w,h);if(!pts.length){if(axes){x.fillStyle='#9aaac1';x.font='13px system-ui';x.fillText('Data unavailable',12,28)}return}let t0=Math.min(...pts.map(p=>p.t)),t1=Math.max(...pts.map(p=>p.t));if(t1===t0)t1+=3600000;let lo=Math.min(...pts.map(p=>p.v)),hi=Math.max(...pts.map(p=>p.v)),m=(hi-lo||Math.abs(hi)*.02||1)*.08;lo-=m;hi+=m;const span=t1-t0;if(axes){x.font='10px system-ui';for(let i=0;i<5;i++){const frac=i/4,y=pad.t+(h-pad.t-pad.b)*frac,val=hi-(hi-lo)*frac;x.strokeStyle='#273750';x.beginPath();x.moveTo(pad.l,y);x.lineTo(w-pad.r,y);x.stroke();x.fillStyle='#9aaac1';x.fillText(axisValue(val),4,y+3)}const seen=new Set();for(let i=0;i<5;i++){const t=t0+(t1-t0)*i/4,txt=axisDate(t,span);if(seen.has(txt))continue;seen.add(txt);const px=pad.l+(t-t0)/(t1-t0)*(w-pad.l-pad.r),tw=x.measureText(txt).width;x.fillStyle='#9aaac1';x.fillText(txt,Math.max(pad.l,Math.min(w-pad.r-tw,px-tw/2)),h-7)}}for(const ss of list){if(!ss.data?.length)continue;x.strokeStyle=ss.color;x.lineWidth=axes?2:1.7;x.beginPath();ss.data.forEach((p,i)=>{const px=pad.l+(p.t-t0)/(t1-t0)*(w-pad.l-pad.r),py=pad.t+(hi-p.v)/(hi-lo)*(h-pad.t-pad.b);i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke()}if(axes){const inspect=e=>{e.stopPropagation();tooltip(c,e,list,pad,t0,t1)};c.onpointerdown=inspect;c.onpointermove=e=>{if(e.pointerType==='mouse'||e.buttons)inspect(e)};c.onpointerleave=()=>$('#chartTip')?.remove()}}function tooltip(c,e,list,pad,t0,t1)'''
s=s[:m.start()]+chart+s[m.end():]
s=s.replace("drawLines(c,[{name:META[id].short,color:META[id].color,unit:(META[id].unit||'')+(META[id].suffix||''),data:exactRangeSeries(id,r)}])","drawLines(c,[{name:META[id].short,color:META[id].color,unit:(META[id].unit||'')+(META[id].suffix||''),data:exactRangeSeries(id,r)}],{axes:false})")

# Intraday detail for 1D/5D; long horizons use pre-cooked daily aggregate. Add a linear back-to-components action.
m=re.search(r"async function drawInstrument\(\).*?function renderInstrument\(id,r\).*?\}\nfunction renderMacro",s,re.S)
if not m: raise SystemExit('instrument functions not found')
instrument=r'''function detailBackButton(){return`<button class="secondary" id="backToComponentsBtn" style="margin-right:8px">← Components</button>`}function bindDetailBack(){const b=$('#backToComponentsBtn');if(b)b.onclick=()=>{showSection('now','overview');if(state.lastComposite)setTimeout(()=>openComposite(state.lastComposite),0)}}async function drawIntradayInstrument(id,r){const h=HORIZONS[r],m=META[id];$('#instrumentLoading').innerHTML=`<div><strong>Loading ${esc(m.short)} ${h.label}</strong><br><span class="muted">${h.interval} observations for the short-term view.</span></div>`;$('#instrumentLoading').classList.add('show');try{const d=await fetchYahoo(id,h.fetchRange,h.interval);drawLines($('#instrumentChart'),[{name:m.short,color:m.color,unit:(m.unit||'')+(m.suffix||''),data:d}]);const q=quote(d);$('#instrumentStatus').innerHTML=`${detailBackButton()}<strong>${esc(m.name)}</strong> · ${h.label} · ${d.length} observations`;$('#instrumentDetail').innerHTML=`${esc(m.description)}<br><span class="muted">Short horizons use intraday observations. Latest ${(m.unit||'')+fmt(q.value,m.decimals)+(m.suffix||'')}.</span>`;bindDetailBack()}catch(e){drawLines($('#instrumentChart'),[]);$('#instrumentStatus').innerHTML=`${detailBackButton()}<strong>${esc(m.name)}</strong> · <span class="badText">${h.label} unavailable</span>`;$('#instrumentDetail').textContent='The intraday provider could not supply this short-term view.';bindDetailBack()}finally{$('#instrumentLoading').classList.remove('show')}}async function drawInstrument(){const id=$('#instrumentSelect').value,r=$('#instrumentRange').value,m=META[id];if(HORIZONS[r]?.intraday)return drawIntradayInstrument(id,r);let cov=coverage(id,r==='max'?'5y':r);if(!cov.ok){$('#instrumentLoading').innerHTML=`<div><strong>Preparing ${esc(m.short)} history for ${HORIZONS[r]?.label||r}…</strong><br><span class="muted">The chart remains blank until the requested history is actually present.</span></div>`;$('#instrumentLoading').classList.add('show');await ensureHistory(id,r);$('#instrumentLoading').classList.remove('show');cov=coverage(id,r==='max'?'5y':r)}if(!cov.ok){drawLines($('#instrumentChart'),[]);$('#instrumentStatus').innerHTML=`${detailBackButton()}<strong>${esc(m.name)}</strong> · <span class="badText">${HORIZONS[r]?.label||r} unavailable</span> · ${cov.points}/${cov.required||'—'} observations`;$('#instrumentDetail').textContent='Historical coverage is incomplete or the provider could not supply the requested period. The chart is intentionally blank.';bindDetailBack();return}renderInstrument(id,r)}function renderInstrument(id,r){const actual=r==='max'?'5y':r,d=r==='max'?(state.series[id]||[]):exactRangeSeries(id,actual),m=META[id],q=quote(d);if(!d.length){drawLines($('#instrumentChart'),[]);return}drawLines($('#instrumentChart'),[{name:m.short,color:m.color,unit:(m.unit||'')+(m.suffix||''),data:d}]);$('#instrumentStatus').innerHTML=`${detailBackButton()}<strong>${esc(m.name)}</strong> · ${HORIZONS[r]?.label||r} · ${d.length} daily observations · ${new Date(d[0].t).toLocaleDateString()} → ${new Date(d.at(-1).t).toLocaleDateString()}`;$('#instrumentDetail').innerHTML=`${esc(m.description)}<br><span class="muted">Latest ${(m.unit||'')+fmt(q.value,m.decimals)+(m.suffix||'')}; period change ${pct(q.periodPct)}. Source: ${esc(displayProvider(state.seriesMeta[id]?.provider))}.</span>`;bindDetailBack()}
function renderMacro'''
s=s[:m.start()]+instrument+s[m.end():]

# Historical regime priming: daily one-month-lookback score for one rolling year from the already-collected market foundation.
insert=r'''function valueAtOrBefore(id,ts){const d=state.series[id]||[];let lo=0,hi=d.length-1,best=null;while(lo<=hi){const mid=(lo+hi)>>1;if(d[mid].t<=ts){best=d[mid];lo=mid+1}else hi=mid-1}return best}function historicalSignal(id,ts){const a=valueAtOrBefore(id,ts),b=valueAtOrBefore(id,ts-30*86400000);if(!a||!b||!b.v)return null;return signal(id,{periodPct:(a.v/b.v-1)*100})}function historicalComposite(key,ts){const vals=COMPOSITES[key].components.map(id=>historicalSignal(id,ts)).filter(Boolean);if(!vals.length)return null;return vals.reduce((a,b)=>a+b.score,0)/vals.length}async function primeRegimeHistory(){const end=commonEnd(),start=end-365*86400000,dates=(state.series.spy||[]).filter(x=>x.t>=start&&x.t<=end).map(x=>x.t);if(!dates.length)return;const existing=new Set(state.history.filter(x=>x.derived).map(x=>new Date(x.ts).toISOString().slice(0,10))),todo=dates.filter(ts=>!existing.has(new Date(ts).toISOString().slice(0,10)));if(!todo.length)return;progressOpen('Calculating one-year regime history',todo.length);let done=0;try{for(const ts of todo){const vals=['risk','rates','energy','defense'].map(k=>historicalComposite(k,ts)).filter(v=>v!==null);if(vals.length){const raw=vals.reduce((a,b)=>a+b,0)/vals.length,score=Math.round(50+raw*35),row={id:'derived:'+new Date(ts).toISOString().slice(0,10),ts,score,regime:score>=62?'Optimistic':score<=38?'Pessimistic':'Neutral',confidence:Math.round(vals.length/4*100),horizon:'1mo',derived:true};await idbPut('regimeHistory',row);state.history.push(row)}done++;if(done%10===0||done===todo.length)progressStep(done,todo.length,'Daily regime snapshots')}}finally{state.history.sort((a,b)=>a.ts-b.ts);progressClose();renderRegimeChart()}}'''
replace_once("function renderRegimeChart(){",insert+"function renderRegimeChart(){","regime history helpers")
s=s.replace("const rows=state.history.slice(-200).map(x=>({t:x.ts,v:x.score}));","const cutoff=commonEnd()-365*86400000,rows=state.history.filter(x=>Number.isFinite(x.score)&&x.ts>=cutoff).map(x=>({t:x.ts,v:x.score}));")
s=s.replace("async function saveRegimeSnapshot(force=false){const r=regime(),last=state.history.at(-1),now=Date.now();","async function saveRegimeSnapshot(force=false){const r=regime();if(!Number.isFinite(r.score))return;const last=state.history.at(-1),now=Date.now();")

# Bootstrap 5Y once; mark complete only after data pass; then prime daily historical regime.
m=re.search(r"async function bootstrapHistory\(\).*?\}async function init\(\).*?\}init\(\);",s,re.S)
if not m: raise SystemExit('bootstrap/init block not found')
boot=r'''async function bootstrapHistory(){const key='mn-history-bootstrap-5y',last=+(localStorage.getItem(key)||0),ids=['spy','qqq','vix','tenYear','wti','brent','gold','dxy'],missing=ids.filter(id=>!coverage(id,'5y').ok);if(!missing.length){localStorage.setItem(key,String(Date.now()));await primeRegimeHistory();return}if(Date.now()-last<30*60000)return;progressOpen('Building five-year market foundation',missing.length);let done=0;try{for(const id of missing){progressStep(done,missing.length,`Fetching ${META[id].short}`);await ensureHistory(id,'5y');done++;progressStep(done,missing.length,META[id].short);renderNow();await new Promise(x=>setTimeout(x,250))}if(ids.every(id=>coverage(id,'5y').ok))localStorage.setItem(key,String(Date.now()))}finally{progressClose()}await primeRegimeHistory()}async function init(){loadConfig();state.providers=readSmall('mn-provider-health',{});await openDb();await loadDbState();bind();renderAll();const h=location.hash.slice(1).split('/');showSection(NAV.some(x=>x[0]===h[0])?h[0]:'now',h[1]);schedule();$('#lastUpdated').textContent='Stored data loaded';collect().catch(e=>log(e.message,'warning'));bootstrapHistory().catch(e=>log('History bootstrap: '+e.message,'warning'))}init();'''
s=s[:m.start()]+boot+s[m.end():]

# Show Market Detail title when reached through the guided drilldown even though Markets is no longer a sidebar destination.
s=s.replace("$('#pageTitle').textContent=NAV.find(x=>x[0]===id)?.[2]||id;","$('#pageTitle').textContent=NAV.find(x=>x[0]===id)?.[2]||(id==='markets'?'Market Detail':id);")

p.write_text(s)
print('Patched Market Navigator to 3.6')
